INSERT INTO `wp_options` VALUES (890,'elementor_custom_css','\n.elementor-kit-ahonga-komlavi .elementor-widget-heading {\n    color: var(--e-global-color-primary) !important;\n}\n\n.elementor-kit-ahonga-komlavi .elementor-button {\n    background-color: var(--e-global-color-primary) !important;\n    color: #1A1A1A !important;\n    border-radius: 8px !important;\n    font-weight: 600 !important;\n    padding: 14px 36px !important;\n}\n\n.elementor-kit-ahonga-komlavi .elementor-button:hover {\n    background-color: #FFB84D !important;\n    transform: translateY(-2px) !important;\n}\n\n.elementor-kit-ahonga-komlavi .elementor-section {\n    padding: 80px 0 !important;\n}\n\n.elementor-kit-ahonga-komlavi .elementor-icon-box {\n    background: #FFFFFF !important;\n    border: 1px solid #E8E8E8 !important;\n    border-radius: 12px !important;\n    padding: 32px !important;\n    text-align: center !important;\n    transition: all 0.3s ease !important;\n}\n\n.elementor-kit-ahonga-komlavi .elementor-icon-box:hover {\n    transform: translateY(-4px) !important;\n    box-shadow: 0 8px 32px rgba(0,0,0,0.08) !important;\n    border-color: var(--e-global-color-primary) !important;\n}\n\n.elementor-kit-ahonga-komlavi .elementor-icon-box__icon {\n    color: var(--e-global-color-primary) !important;\n}\n\n.elementor-kit-ahonga-komlavi .elementor-icon-box__title {\n    color: var(--e-global-color-text) !important;\n    font-size: 1.25rem !important;\n    font-weight: 600 !important;\n}\n\n.elementor-kit-ahonga-komlavi .elementor-icon-box__text {\n    color: #555555 !important;\n    line-height: 1.7 !important;\n}\n\n.donation-section {\n    background: #FFFDF9 !important;\n    border-radius: 16px !important;\n    padding: 40px !important;\n    max-width: 500px !important;\n    margin: 40px auto !important;\n}\n\n.donation-section h3 {\n    color: var(--e-global-color-secondary) !important;\n    font-size: 1.5rem !important;\n    margin-bottom: 20px !important;\n}\n\n.phone-item {\n    display: flex !important;\n    align-items: center !important;\n    gap: 12px !important;\n    padding: 12px 0 !important;\n    border-bottom: 1px solid #E8E8E8 !important;\n}\n\n.phone-item:last-child {\n    border-bottom: none !important;\n}\n\n.section-divider {\n    height: 1px !important;\n    background: #E8E8E8 !important;\n    margin: 0 auto 60px !important;\n    max-width: 1200px !important;\n}\n\n.elementor-form__field {\n    border: 1px solid #E8E8E8 !important;\n    border-radius: 8px !important;\n    padding: 12px 16px !important;\n    margin-bottom: 16px !important;\n}\n\n.elementor-form__field:focus {\n    outline: none !important;\n    border-color: var(--e-global-color-primary) !important;\n}\n\n.elementor-form__submit {\n    background-color: var(--e-global-color-primary) !important;\n    color: #1A1A1A !important;\n    border-radius: 8px !important;\n    font-weight: 600 !important;\n    padding: 14px 40px !important;\n}\n\n.elementor-kit-ahonga-komlavi h1,\n.elementor-kit-ahonga-komlavi h2,\n.elementor-kit-ahonga-komlavi h3,\n.elementor-kit-ahonga-komlavi h4 {\n    font-family: \'Inter\', sans-serif !important;\n    font-weight: 600 !important;\n    letter-spacing: -0.5px !important;\n}\n\n.elementor-kit-ahonga-komlavi p,\n.elementor-kit-ahonga-komlavi li {\n    font-family: \'Inter\', sans-serif !important;\n    line-height: 1.7 !important;\n}\n\n@media (max-width: 768px) {\n    .elementor-section {\n        padding: 50px 0 !important;\n    }\n    .elementor-widget-heading h1 {\n        font-size: 2.2rem !important;\n    }\n}\n','auto');
