d_hover_image_tablet\":{\"url\":\"\",\"id\":\"\"},\"background_hover_image_mobile\":{\"url\":\"\",\"id\":\"\"},\"background_hover_video_fallback\":{\"url\":\"\",\"id\":\"\"},\"background_hover_slideshow_gallery\":[],\"background_overlay_image\":{\"url\":\"\",\"id\":\"\"},\"background_overlay_image_tablet\":{\"url\":\"\",\"id\":\"\"},\"background_overlay_image_mobile\":{\"url\":\"\",\"id\":\"\"},\"background_overlay_video_fallback\":{\"url\":\"\",\"id\":\"\"},\"background_overlay_slideshow_gallery\":[],\"background_overlay_hover_image\":{\"url\":\"\",\"id\":\"\"},\"background_overlay_hover_image_tablet\":{\"url\":\"\",\"id\":\"\"},\"background_overlay_hover_image_mobile\":{\"url\":\"\",\"id\":\"\"},\"background_overlay_hover_video_fallback\":{\"url\":\"\",\"id\":\"\"},\"background_overlay_hover_slideshow_gallery\":[]},\"elements\":[{\"id\":\"7faa7b0b\",\"elType\":\"widget\",\"settings\":{\"icon_list\":[{\"text\":\"We are asking that anyone who is experiencing symptoms or feeling ill to reschedule their appointments.\",\"selected_icon\":{\"value\":\"vamtamtheme- vamtam-theme-check\",\"library\":\"theme-icons\"},\"_id\":\"ad9af92\",\"link\":{\"url\":\"\",\"is_external\":\"\",\"nofollow\":\"\",\"custom_attributes\":\"\"}},{\"text\":\"Everyone entering the studio is required to take a health screening upon entering the studio.\",\"selected_icon\":{\"value\":\"vamtamtheme- vamtam-theme-check\",\"library\":\"theme-icons\"},\"_id\":\"94948fb\",\"link\":{\"url\":\"\",\"is_external\":\"\",\"nofollow\":\"\",\"custom_attributes\":\"\"}},{\"text\":\"We ask that all trainers and clients wash their hands before and after every session.\",\"selected_icon\":{\"value\":\"vamtamtheme- vamtam-theme-check\",\"library\":\"theme-icons\"},\"_id\":\"55f3f4a\",\"link\":{\"url\":\"\",\"is_external\":\"\",\"nofollow\":\"\",\"custom_attributes\":\"\"}},{\"text\":\"Masks are required to enter and must be worn at all times. If you have forgotten your mask, please stop by the Front Desk for a mask.\",\"selected_icon\":{\"value\":\"vamtamtheme- vamtam-theme-check\",\"library\":\"theme-icons\"},\"_id\":\"b59aab9\",\"link\":{\"url\":\"\",\"is_external\":\"\",\"nofollow\":\"\",\"custom_attributes\":\"\"}},{\"text\":\" You will be required to stay within the slot on the floor you have booked for your session. TRAINERS: Please gather all equipment you will need at the beginning of your session, keep with you during the session and sanitize afterward.\",\"selected_icon\":{\"value\":\"vamtamtheme- vamtam-theme-check\",\"library\":\"theme-icons\"},\"_id\":\"2112aec\",\"link\":{\"url\":\"\",\"is_external\":\"\",\"nofollow\":\"\",\"custom_attributes\":\"\"}},{\"text\":\"Please maintain a 6ft distance during your sessions and while using any areas of the studio.\",\"selected_icon\":{\"value\":\"vamtamtheme- vamtam-theme-check\",\"library\":\"theme-icons\"},\"_id\":\"3bcecb6\",\"link\":{\"url\":\"\",\"is_external\":\"\",\"nofollow\":\"\",\"custom_attributes\":\"\"}}],\"space_between\":{\"unit\":\"px\",\"size\":30,\"sizes\":[]},\"icon_size\":{\"unit\":\"px\",\"size\":17,\"sizes\":[]},\"icon_self_align\":\"left\",\"text_indent\":{\"unit\":\"px\",\"size\":20,\"sizes\":[]},\"_background_image\":{\"url\":\"\",\"id\":\"\"},\"_background_image_tablet\":{\"url\":\"\",\"id\":\"\"},\"_background_image_mobile\":{\"url\":\"\",\"id\":\"\"},\"_background_video_fallback\":{\"url\":\"\",\"id\":\"\"},\"_background_slideshow_gallery\":[],\"_background_hover_image\":{\"url\":\"\",\"id\":\"\"},\"_background_hover_image_tablet\":{\"url\":\"\",\"id\":\"\"},\"_background_hover_image_mobile\":{\"url\":\"\",\"id\":\"\"},\"_background_hover_video_fallback\":{\"url\":\"\",\"id\":\"\"},\"_background_hover_slideshow_gallery\":[]},\"elements\":[],\"widgetType\":\"icon-list\"}],\"isInner\":false},{\"id\":\"5d8b129a\",\"elType\":\"column\",\"settings\":{\"_column_size\":50,\"_inline_size\":null,\"padding\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"65\",\"isLinked\":false},\"padding_tablet\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"15\",\"isLinked\":false},\"padding_mobile\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":true},\"background_image\":{\"url\":\"\",\"id\":\"\"},\"background_image_tablet\":{\"url\":\"\",\"id\":\"\"},\"background_image_mobile\":{\"url\":\"\",\"id\":\"\"},\"background_video_fallback\":{\"url\":\"\",\"id\":\"\"},\"background_slideshow_gallery\":[],\"background_hover_image\":{\"url\":\"\",\"id\":\"\"},\"background_hover_image_tablet\":{\"url\":\"\",\"id\":\"\"},\"background_hover_image_mobile\":{\"url\":\"\",\"id\":\"\"},\"background_hover_video_fallback\":{\"url\":\"\",\"id\":\"\"},\"background_hover_slideshow_gallery\":[],\"background_overlay_image\":{\"url\":\"\",\"id\":\"\"},\"background_overlay_image_tablet\":{\"url\":\"\",\"id\":\"\"},\"background_overlay_image_mobile\":{\"url\":\"\",\"id\":\"\"},\"background_overlay_video_fallback\":{\"url\":\"\",\"id\":\"\"},\"background_overlay_slideshow_gallery\":[],\"background_overlay_hover_image\":{\"url\":\"\",\"id\":\"\"},\"background_overlay_hover_image_tablet\":{\"url\":\"\",\"id\":\"\"},\"background_overlay_hover_image_mobile\":{\"url\":\"\",\"id\":\"\"},\"background_overlay_hover_video_fallback\":{\"url\":\"\",\"id\":\"\"},\"background_overlay_hover_slideshow_gallery\":[]},\"elements\":[{\"id\":\"6d1fe4a1\",\"elType\":\"widget\",\"settings\":{\"icon_list\":[{\"text\":\"Please book your sessions 24 hrs. in advance. This is important information for us to know so we can be certain we are maintaining our capacity requirements. NO WALK-INS PLEASE.\",\"selected_icon\":{\"value\":\"vamtamtheme- vamtam-theme-check\",\"library\":\"theme-icons\"},\"_id\":\"ad9af92\",\"link\":{\"url\":\"\",\"is_external\":\"\",\"nofollow\":\"\",\"custom_attributes\":\"\"}},{\"text\":\"We are disinfecting all equipment on an hourly basis and require trainers and clients to wipe down any equipment or mats 