INSERT INTO `wp_postmeta` VALUES (2901,37189,'_elementor_data','[{\"id\":\"4b41e8b\",\"elType\":\"section\",\"settings\":{\"padding\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false},\"content_width\":{\"unit\":\"px\",\"size\":952,\"sizes\":[]},\"margin_tablet\":{\"unit\":\"px\",\"top\":\"0\",\"right\":0,\"bottom\":\"0\",\"left\":0,\"isLinked\":false},\"padding_tablet\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"30\",\"bottom\":\"0\",\"left\":\"30\",\"isLinked\":false},\"padding_mobile\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"20\",\"bottom\":\"0\",\"left\":\"20\",\"isLinked\":false}},\"elements\":[{\"id\":\"3c60424\",\"elType\":\"column\",\"settings\":{\"_column_size\":100,\"_inline_size\":null,\"padding\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false},\"space_between_widgets_tablet\":10},\"elements\":[{\"id\":\"590b385\",\"elType\":\"widget\",\"settings\":{\"title\":\"How you  can help\\n\",\"header_size\":\"h3\"},\"elements\":[],\"widgetType\":\"heading\"},{\"id\":\"f461d72\",\"elType\":\"widget\",\"settings\":{\"editor\":\"<p>You can designate funds to an emergency response, make an unrestricted annual gift or recommend recurring payments to a special appeal. Another option is to support programs that meet your interests, such as maternal and newborn health, early childhood education, gender equality, child rights and more.<br \\/><br \\/>A donor-advised fund allows you to give back to a cause that\\u2019s close to your heart. It\\u2019s an opportunity to put your charitable dollars to work \\u2013 where the need is great \\u2013 but on your own terms. Thus, you have flexibility to tailor your philanthropic giving in easy, cost-effective ways.<\\/p>\",\"_margin_tablet\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":true},\"_padding_tablet\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":true}},\"elements\":[],\"widgetType\":\"text-editor\"},{\"id\":\"b059c83\",\"elType\":\"widget\",\"settings\":{\"title\":\"This is the exact decision that Enbridge\\u2019s wanted.\\n\",\"header_size\":\"h3\",\"_margin\":{\"unit\":\"px\",\"top\":\"30\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false},\"_margin_tablet\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":true}},\"elements\":[],\"widgetType\":\"heading\"},{\"id\":\"7130606\",\"elType\":\"widget\",\"settings\":{\"editor\":\"But that money can\\u2019t drown out the voices of Minnesotans who have repeatedly said they do not want this pipeline. Over 90 percent of the public comments submitted to the Public Utilities Commission opposed Line 3, and that should matter more than Enbridge\\u2019s dollars.\\n\\n\"},\"elements\":[],\"widgetType\":\"text-editor\"},{\"id\":\"e764964\",\"elType\":\"widget\",\"settings\":{\"title\":\"Obama Protects the Arctic Ocean\\n\\n\",\"header_size\":\"h3\",\"_margin\":{\"unit\":\"px\",\"top\":\"30\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false},\"_margin_tablet\":{\"unit\":\"px\",\"top\":\"20\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false}},\"elements\":[],\"widgetType\":\"heading\"},{\"id\":\"22b3616\",\"elType\":\"widget\",\"settings\":{\"editor\":\"Building on this momentum, thousands of people called on President Obama to use his legal authority to make the U.S. Arctic Ocean off limits from future oil drilling. In late 2016, Obama took action to permanently protect all of the Chukchi Sea and the vast majority of the Beaufort Sea \\u2014 as well as a number of biologically important undersea canyons in the Atlantic.This was a big victory for the people-powered climate movement, signalling that the relentless expansion of the oil industry into new areas was finally at an end.But then Trump happened.\\n\\n\"},\"elements\":[],\"widgetType\":\"text-editor\"}],\"isInner\":false}],\"isInner\":false},{\"id\":\"57f491c\",\"elType\":\"section\",\"settings\":{\"layout\":\"full_width\",\"content_width\":{\"unit\":\"px\",\"size\":1314,\"sizes\":[]},\"margin\":{\"unit\":\"px\",\"top\":\"60\",\"right\":0,\"bottom\":\"60\",\"left\":0,\"isLinked\":false},\"padding\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false},\"margin_tablet\":{\"unit\":\"px\",\"top\":\"40\",\"right\":0,\"bottom\":\"40\",\"left\":0,\"isLinked\":true},\"padding_tablet\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"30\",\"bottom\":\"0\",\"left\":\"30\",\"isLinked\":false},\"padding_mobile\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"20\",\"bottom\":\"0\",\"left\":\"20\",\"isLinked\":false}},\"elements\":[{\"id\":\"200b73c\",\"elType\":\"column\",\"settings\":{\"_column_size\":100,\"_inline_size\":null,\"background_background\":\"classic\",\"background_image\":{\"url\":\"https:\\/\\/caridad.vamtam.com\\/wp-content\\/uploads\\/2020\\/10\\/tucker-tangeman-IrtRZ-6HxIE-unsplash.jpg\",\"id\":25812},\"background_position\":\"center center\",\"background_repeat\":\"no-repeat\",\"margin\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false},\"padding\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false},\"background_position_mobile\":\"center center\"},\"elements\":[{\"id\":\"f9a3a31\",\"elType\":\"widget\",\"settings\":{\"space\":{\"unit\":\"px\",\"size\":600,\"sizes\":[]},\"space_tablet\":{\"unit\":\"px\",\"size\":402,\"sizes\":[]},\"space_mobile\":{\"unit\":\"px\",\"size\":200,\"sizes\":[]}},\"elements\":[],\"widgetType\":\"spacer\"}],\"isInner\":false}],\"isInner\":false},{\"id\":\"fd12401\",\"elType\":\"section\",\"settings\":{\"padding\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false},\"content_width\":{\"unit\":\"px\",\"size\":952,\"sizes\":[]},\"margin\":{\"unit\":\"px\",\"top\":\"0\",\"right\":0,\"bottom\":\"0\",\"left\":0,\"isLinked\":false},\"margin_tablet\":{\"unit\":\"px\",\"top\":\"0\",\"right\":0,\"bottom\":\"0\",\"left\":0,\"isLinked\":false},\"padding_tablet\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"30\",\"bottom\":\"0\",\"left\":\"30\",\"isLinked\":false},\"padding_mobile\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"20\",\"bottom\":\"0\",\"left\":\"20\",\"isLinked\":false}},\"elements\":[{\"id\":\"5d05895\",\"elType\":\"column\",\"settings\":{\"_column_size\":100,\"_inline_size\":null,\"padding\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false},\"space_between_widgets_tablet\":10},\"elements\":[{\"id\":\"3612152\",\"elType\":\"widget\",\"settings\":{\"title\":\"The Trump Twist\\n\",\"header_size\":\"h3\"},\"elements\":[],\"widgetType\":\"heading\"},{\"id\":\"98aa5de\",\"elType\":\"widget\",\"settings\":{\"editor\":\"<p>Trump came into office calling climate change a hoax and giving handouts to dirty energy companies. His plan to open up nearly every U.S. coastline to more oil and gas drilling was extremely unpopular, and in the case of the Arctic Ocean, it outright ignored the fact that Obama had already ruled out future leasing there.<\\/p><p>Trump\\u2019s new offshore oil plan called for lease sales in the Beaufort Sea starting in 2019 and the Chukchi Sea in 2020. In response, Greenpeace joined with other groups in a lawsuit to challenge the plan in court. Earthjustice and the Natural Resources Defense Council led the litigation, representing Greenpeace along with Alaska Wilderness League, Center for Biological Diversity, Defenders of Wildlife, League of Conservation Voters, Northern Alaska Environmental Center, Resisting Environmental Destruction on Indigenous Lands (REDOIL), Sierra Club, and the Wilderness Society.<\\/p>\",\"_margin_tablet\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false},\"_padding_tablet\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false}},\"elements\":[],\"widgetType\":\"text-editor\"}],\"isInner\":false}],\"isInner\":false},{\"id\":\"2caa9c0\",\"elType\":\"section\",\"settings\":{\"content_width\":{\"unit\":\"px\",\"size\":741,\"sizes\":[]},\"padding_mobile\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"30\",\"bottom\":\"0\",\"left\":\"30\",\"isLinked\":false},\"margin\":{\"unit\":\"px\",\"top\":\"20\",\"right\":0,\"bottom\":\"35\",\"left\":0,\"isLinked\":false}},\"elements\":[{\"id\":\"4859afa\",\"elType\":\"column\",\"settings\":{\"_column_size\":100,\"_inline_size\":null,\"padding_tablet\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"30\",\"bottom\":\"0\",\"left\":\"30\",\"isLinked\":false},\"padding_mobile\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false}},\"elements\":[{\"id\":\"04662ec\",\"elType\":\"widget\",\"settings\":{\"blockquote_skin\":\"quotation\",\"blockquote_content\":\"The key issue was that when Congress enacted the Outer Continental Shelf Lands Act (OCSLA), it gave the president authority to withdraw areas from oil and gas leasing, but made no mention of revoking previous withdrawals.\",\"author_name\":\"John Doe\",\"tweet_button_view\":\"icon\",\"tweet_button_label\":\"Tweet\",\"content_typography_typography\":\"custom\",\"content_typography_font_size\":{\"unit\":\"px\",\"size\":20,\"sizes\":[]},\"content_typography_line_height\":{\"unit\":\"em\",\"size\":1.5,\"sizes\":[]},\"content_gap\":{\"unit\":\"px\",\"size\":20,\"sizes\":[]},\"author_typography_typography\":\"custom\",\"author_typography_font_size\":{\"unit\":\"px\",\"size\":20,\"sizes\":[]},\"button_size\":{\"unit\":\"px\",\"size\":1.6,\"sizes\":[]},\"button_border_radius\":{\"unit\":\"px\",\"size\":50,\"sizes\":[]},\"button_color_source\":\"custom\",\"button_text_color\":\"#052F5C\",\"quote_text_color\":\"#F69D94\",\"quote_size\":{\"unit\":\"px\",\"size\":1.4,\"sizes\":[]},\"quote_gap\":{\"unit\":\"px\",\"size\":0,\"sizes\":[]},\"__globals__\":{\"quote_text_color\":\"globals\\/colors?id=vamtam_accent_1\",\"button_background_color\":\"globals\\/colors?id=vamtam_accent_5\",\"button_text_color\":\"globals\\/colors?id=vamtam_accent_6\",\"author_text_color\":\"globals\\/colors?id=vamtam_accent_6\",\"content_text_color\":\"globals\\/colors?id=vamtam_accent_6\",\"button_background_color_hover\":\"\",\"button_text_color_hover\":\"globals\\/colors?id=vamtam_accent_2\"},\"content_text_color\":\"#052F5C\",\"author_text_color\":\"#052F5C\",\"button_typography_typography\":\"custom\",\"button_text_color_hover\":\"#F69D94\"},\"elements\":[],\"widgetType\":\"blockquote\"}],\"isInner\":false}],\"isInner\":false},{\"id\":\"3a1f6f0\",\"elType\":\"section\",\"settings\":{\"padding_tablet\":{\"unit\":\"px\",\"top\":\"20\",\"right\":\"30\",\"bottom\":\"0\",\"left\":\"30\",\"isLinked\":false},\"padding_mobile\":{\"unit\":\"px\",\"top\":\"20\",\"right\":\"20\",\"bottom\":\"0\",\"left\":\"20\",\"isLinked\":false},\"gap\":\"no\",\"padding\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false}},\"elements\":[{\"id\":\"dbcac8b\",\"elType\":\"column\",\"settings\":{\"_column_size\":100,\"_inline_size\":null,\"padding_tablet\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false}},\"elements\":[{\"id\":\"033e6fc\",\"elType\":\"widget\",\"settings\":{\"editor\":\"That\\u2019s an act that only Congress itself can take. Judge Sharon Gleason agreed with this analysis, and as she stated in her ruling, Obama\\u2019s withdrawals \\u201cwill remain in full force and effect unless and until revoked by Congress.\\u201d The government may appeal this ruling, but for now this is a big victory for the climate.\\n\\n\"},\"elements\":[],\"widgetType\":\"text-editor\"}],\"isInner\":false}],\"isInner\":false}]');
