INSERT INTO `wp_posts` VALUES (40065,0,'2021-04-06 13:51:52','2021-04-06 13:51:52','<a href=\"#\">\n									<h3>\n						Afterschool Meals					</h3>\n						Providing nutritious meals for afterschool programs.					\n						</a>\n			<h3>Summer Nutrition</h3>		\n		When school is out of session, we ensure kids can still access meals.		\n																					<img width=\"77\" height=\"73\" src=\"https://caridad.vamtam.com/wp-content/uploads/2021/04/sun.svg\" alt=\"\" loading=\"lazy\" />																								\n			<h3>Nutrition Education</h3>		\n		Teaching kids and caretakers how to eat healthy and get active.		\n																					<img width=\"72\" height=\"75\" src=\"https://caridad.vamtam.com/wp-content/uploads/2021/04/apple.svg\" alt=\"\" loading=\"lazy\" />																								\n					<a href=\"#\">\n									<h3>\n						School Breakfast					</h3>\n						Helping students get a healthy start to their school day.					\n						</a>','How we help - First try ( for erease )','','publish','closed','closed','','how-we-help-first-try-for-erease','','','2021-04-06 13:51:52','2021-04-06 13:51:52','',0,'https://caridad.vamtam.com/?elementor_library=how-we-help-first-try-for-erease',0,'elementor_library','',0);
