INSERT INTO `wp_posts` VALUES (44793,0,'2026-09-07 17:16:53','2026-09-07 15:16:53','\n<div class=\"hero-section\">\n    <h1>Évangéliste Ahonga Komlavi</h1>\n    <p>Servant la parole de Dieu avec fidélité, compassion et espérance. Une communauté de foi, d\'amour et d\'espérance au cœur du Togo.</p>\n    <a href=\"#donations\" class=\"btn-primary-joy\">Faire un don</a>\n    <a href=\"/blog\" class=\"btn-secondary-joy\">Découvrir nos prêches</a>\n</div>\n\n<div class=\"joy-section\">\n    <div class=\"section-divider\" style=\"margin-bottom:60px\"></div>\n    <h2 style=\"text-align:center;font-size:2.5rem;color:var(--joy-text);margin-bottom:10px\">Nos valeurs</h2>\n    <p style=\"text-align:center;color:var(--joy-text-soft);max-width:600px;margin:0 auto 50px\">Ce qui nous anime chaque jour</p>\n    \n    <div style=\"display:grid;grid-template-columns:repeat(auto-fit,minmax(250px,1fr));gap:30px;max-width:1100px;margin:0 auto\">\n        <div class=\"feature-card\">\n            <div class=\"feature-icon\">✨</div>\n            <h3>Foi</h3>\n            <p>Nous croyons en la puissance de la parole de Dieu pour transformer les vies et construire l\'avenir.</p>\n        </div>\n        <div class=\"feature-card\">\n            <div class=\"feature-icon\">❤️</div>\n            <h3>Compassion</h3>\n            <p>Nous servons avec un cœur ouvert, portant secours à ceux qui sont dans le besoin sans distinction.</p>\n        </div>\n        <div class=\"feature-card\">\n            <div class=\"feature-icon\">🌟</div>\n            <h3>Espérance</h3>\n            <p>Nous portons l\'espérance d\'un avenir meilleur, par la grâce de Jésus-Christ, pour chaque famille.</p>\n        </div>\n    </div>\n</div>\n\n<div class=\"joy-section\" style=\"background:var(--joy-bg-soft)\">\n    <div id=\"donations\" class=\"donation-box\">\n        <h3>🎁 Soutenez notre ministère</h3>\n        <p style=\"margin-bottom:20px;color:var(--joy-text-soft)\">Vos dons nous permettent de servir la communauté et porter l\'évangile au Togo et au-delà.</p>\n        <div class=\"phone-item\">\n            <span class=\"phone-icon\">📱</span>\n            <div>\n                <strong>Yas Togo</strong><br>\n                <span style=\"color:var(--joy-text-soft)\">+228 90 12 34 56</span>\n            </div>\n        </div>\n        <div class=\"phone-item\">\n            <span class=\"phone-icon\">📱</span>\n            <div>\n                <strong>Moov Togo</strong><br>\n                <span style=\"color:var(--joy-text-soft)\">+228 91 98 76 54</span>\n            </div>\n        </div>\n        <div class=\"phone-item\">\n            <span class=\"phone-icon\">📱</span>\n            <div>\n                <strong>MTN Togo</strong><br>\n                <span style=\"color:var(--joy-text-soft)\">+228 96 45 67 89</span>\n            </div>\n        </div>\n    </div>\n</div>\n','Impact','','inherit','closed','closed','','18129-revision-v1','','','2026-09-07 17:16:53','2026-09-07 15:16:53','',18129,'http://ahonga-komlavi.local/?p=44793',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (44794,0,'2026-09-07 17:16:56','2026-09-07 15:16:56','\n<div class=\"joy-section\">\n    <h1 style=\"font-size:2.5rem;color:var(--joy-text);margin-bottom:30px\">À propos</h1>\n    \n    <div style=\"max-width:800px;margin:0 auto\">\n        <div class=\"feature-card\" style=\"text-align:left;margin-bottom:30px\">\n            <h3>📋 Notre mission</h3>\n            <p>L\'Évangéliste Ahonga Komlavi est appelé à porter l\'évangile de Jésus-Christ avec passion et compassion. À travers des prêches, des études bibliques et des actions caritaires, nous cherchons à transformer les vies et à construire une communauté de forte foi à Lomé, Togo.</p>\n        </div>\n\n        <div class=\"feature-card\" style=\"text-align:left;margin-bottom:30px\">\n            <h3>📞 Nous contacter</h3>\n            <p style=\"margin-bottom:8px\"><strong>Téléphone:</strong> +228 90 12 34 56</p>\n            <p style=\"margin-bottom:8px\"><strong>Email:</strong> contact@ahongakomlavi.org</p>\n            <p style=\"margin-bottom:8px\"><strong>Adresse:</strong> Lomé, Togo</p>\n        </div>\n\n        <div class=\"feature-card\" style=\"text-align:left\">\n            <h3>✉️ Envoyez un message</h3>\n            \n                \n                \n                <textarea name=\"message\" rows=\"5\"></textarea>\n                <button type=\"submit\">Envoyer</button>\n            \n        </div>\n    </div>\n</div>\n','About Us','','inherit','closed','closed','','18149-revision-v1','','','2026-09-07 17:16:56','2026-09-07 15:16:56','',18149,'http://ahonga-komlavi.local/?p=44794',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (44795,0,'2026-09-07 17:16:58','2026-09-07 15:16:58','\n<div class=\"joy-section\">\n    <h1 style=\"font-size:2.5rem;color:var(--joy-text);margin-bottom:10px\">Prêche</h1>\n    <p style=\"color:var(--joy-text-soft);margin-bottom:40px\">Découvrez nos prêches, messages et enseignements bibliques.</p>\n    \n    <div style=\"max-width:800px;margin:0 auto\">\n        <div class=\"feature-card\" style=\"text-align:left;margin-bottom:20px\">\n            <h3>📖 Prêches récents</h3>\n            <p style=\"color:var(--joy-text-soft)\">Les prochains prêches seront publiés bientôt. Revenez régulièrement pour découvrir de nouveaux messages de foi et d\'espérance.</p>\n        </div>\n        \n        <div class=\"feature-card\" style=\"text-align:left\">\n            <h3>🎵 Musique et louange</h3>\n            <p style=\"color:var(--joy-text-soft)\">Découvrez nos sessions de louange, cantiques et musique chrétienne pour adorer Dieu en esprit et en vérité.</p>\n        </div>\n    </div>\n</div>\n','Stories','','inherit','closed','closed','','13750-revision-v1','','','2026-09-07 17:16:58','2026-09-07 15:16:58','',13750,'http://ahonga-komlavi.local/?p=44795',0,'revision','',0);
